function formatConceptBlockForCrystalliser(concepts) {
  if (!concepts || concepts.length === 0)
    return "";
  const rows = concepts.map((c) => {
    const parts2 = [`- id: ${c.id}`];
    if (c.summary)
      parts2.push(`  summary: ${c.summary}`);
    if (c.path)
      parts2.push(`  path: ${c.path}`);
    if (c.tags && c.tags.length > 0)
      parts2.push(`  tags: [${c.tags.join(", ")}]`);
    return parts2.join("\n");
  });
  return [
    "",
    "RELEVANT KNOWLEDGE (OKF concepts supplied by the caller; DO NOT invent new ids):",
    ...rows,
    ""
  ].join("\n");
}
