    if (!row2?.worktree_path)
      return null;
    const planBase = this.planBaseSha(sessionId);
    const headSha = this.deps.worktreeHeadSha ? await this.deps.worktreeHeadSha(row2.worktree_path).catch(() => "") : "";
    const commitsAhead = Boolean(headSha && planBase && headSha !== planBase);
    const dirty = await this.worktreeDirtyFiles(sessionId, row2.worktree_path);
    if (!commitsAhead && dirty.length === 0)
      return null;
